var DIVS=[
 ["Workforce & HR",["Payroll processing (PEO / ASO / self-service)","Time clock & GPS / geofence, PTO","Employee messaging & notifications","Custom employee handbook & HR documents","HRIS & employee management, policy design","Certification / license tracking","Performance management (PMS)","HIPAA-compliant tools","Background checks, drug testing, E-Verify","Garnishments & UI claim administration","Certified payroll (WH-347 / state)"]],
 ["Benefits & Retirement",["Group health (with or without ER contribution)","Individual / personal health options","Benefits administration","Dental, vision, life & ancillary","Pet insurance","401(k) (PEP, MEP, Solo, IRA)","Open enrollment support","ACA compliance & COBRA administration","High-income retirement strategy / design"]],
 ["Financial Services",["Bookkeeping & accounting (AP / AR / inventory)","Tax strategy & preparation, quarterly filings","Financial advisory","QuickBooks integration","Expense tracking & management","Fractional CFO","GL reports","CPA & audited financials","Land acquisition / 1031 exchange"]],
 ["Risk & Insurance",["Workers' comp (monthly reporting, no down payment)","Workers' comp audit","Workers' comp dispute / premium reduction","Workers' comp non-compliant premium refunds","General liability","Professional liability (E&O)","Keyman insurance","Cyber liability","Property & bonding","Bonds / bonding options"]],
 ["Technology & Operations",["Full software stack & CRM","Task & workflow automation","AI Email Assistant","AI Task Agent","Digital / intake forms","Document digitization & form-fill design","Learning management (LMS)","IT support & tech","Programming & workflow automation","Business setup & structure design","AI website design & blogging"]],
 ["Business Consulting",["Vendor audit & optimization","ROI analysis & reporting","Safety training programs & templates","Website & marketing design","Brand & flyer creation","Business strategy consulting","Contracts (W-2 at-will / 1099, multi-state)"]],
 ["Membership",["Membership: Essential","Membership: Professional","Membership: Enterprise","Membership: Concierge / Fractional COO"]]
];
// Build a stable service key from division + item so saved data survives label edits/reordering.
function slug(s){return s.toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'').slice(0,40);}
var SVCKEYS=[]; DIVS.forEach(function(d){d[1].forEach(function(it){SVCKEYS.push(slug(d[0])+'.'+slug(it));});});

var SEL={};        // svcKey -> {on, detail}
var DNOTE={};      // division name -> note text
function el(id){return document.getElementById(id);}
function esc(v){return (v||'').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;');}

function renderSvc(){
 var c=el('svc');c.innerHTML='';var idx=0;
 DIVS.forEach(function(d){
   var dn=d[0], n=0;
   d[1].forEach(function(it){var k=SVCKEYS[idxFor(dn,it)];if(SEL[k]&&SEL[k].on)n++;});
   c.innerHTML+='<div class="divh"><span>'+dn+'</span><span class="cnt" id="cnt_'+slug(dn)+'">'+(n?n+' selected':'')+'</span></div>';
   d[1].forEach(function(item){
     var k=SVCKEYS[idx]; var s=SEL[k]||{on:false,detail:''};
     c.innerHTML+='<div class="srow"><input type="checkbox" data-si="'+idx+'" '+(s.on?'checked':'')+'>'+
       '<span class="lb">'+item+'</span>'+
       '<input class="det" data-sd="'+idx+'" placeholder="details / qty (optional)" value="'+esc(s.detail)+'" '+(s.on?'':'disabled')+'></div>';
     idx++;
   });
   var note=DNOTE[dn]||'';
   c.innerHTML+='<div class="dnote"><textarea data-dn="'+esc(dn)+'" placeholder="Notes for '+dn+', anything that does not fit a checkbox">'+esc(note)+'</textarea></div>';
 });
 c.querySelectorAll('[data-si]').forEach(function(cb){cb.onchange=function(){var i=+cb.dataset.si;var k=SVCKEYS[i];SEL[k]=SEL[k]||{detail:''};SEL[k].on=cb.checked;var d=c.querySelector('[data-sd="'+i+'"]');d.disabled=!cb.checked;if(cb.checked)d.focus();updCnt();};});
 c.querySelectorAll('[data-sd]').forEach(function(inp){inp.oninput=function(){var i=+inp.dataset.sd;var k=SVCKEYS[i];SEL[k]=SEL[k]||{on:true};SEL[k].detail=inp.value;};});
 c.querySelectorAll('[data-dn]').forEach(function(t){t.oninput=function(){DNOTE[t.dataset.dn]=t.value;};});
}
function idxFor(dn,item){return SVCKEYS.indexOf(slug(dn)+'.'+slug(item));}
function updCnt(){DIVS.forEach(function(d){var dn=d[0],n=0;d[1].forEach(function(it){var k=SVCKEYS[idxFor(dn,it)];if(SEL[k]&&SEL[k].on)n++;});var e=el('cnt_'+slug(dn));if(e)e.textContent=n?n+' selected':'';});}

// Documents — stable keys the intake form seeds and the email agent flips.
var DOC_DEFAULT=[
 ["payroll_report","Most recent payroll report / summary","Requested",false,""],
 ["payroll_invoice","Most recent payroll invoice","Requested",false,""],
 ["payroll_report_prior","Prior payroll report (Feb / Mar)","Requested",false,""],
 ["benefits_plan_summary","Current plan documents / summary of benefits","Waiting",false,""],
 ["benefits_invoice","Most recent benefits invoice","Waiting",false,""],
 ["benefits_renewal","Renewal documents / new rates","Not needed",false,""],
 ["census","Employee census (incl. spouse + dependents)","Requested",false,""],
 ["wc_policy","Current workers' comp policy / dec page","Requested",false,""],
 ["business_insurance_docs","Business insurance policies (other lines)","Not needed",false,""],
 ["company_profile","Company profile / other uploads","Not needed",false,""],
 ["signed_bor","Signed Broker of Record form","Not needed",false,""],
 ["signed_no_loss","Signed No-Loss Letter","Not needed",false,""],
 ["handbook","Employee handbook (onboarding)","Not needed",false,""]
];
var DOCS=JSON.parse(JSON.stringify(DOC_DEFAULT));
var DSTAT=['Not needed','Requested','Waiting','Received'];
function statColor(s){return s==='Received'?'background:#eaf3ee;color:#2f6a4f':s==='Requested'?'background:#eef1fb;color:#23304d':s==='Waiting'?'background:#fff4e6;color:#8a5a00':'background:#f2f4f7;color:#8a92a0';}
function renderDocs(){var b=el('docs');b.innerHTML='';DOCS.forEach(function(o,i){
  var opts=DSTAT.map(function(x){return '<option'+(x===o[2]?' selected':'')+'>'+x+'</option>';}).join('');
  b.innerHTML+='<tr class="'+(o[3]?'got':'')+'"><td><div class="doclabel"><input data-dl="'+i+'" value="'+esc(o[1])+'" style="font-weight:600"></div><div class="dockey">'+esc(o[0])+'</div></td>'+
    '<td><select class="stat" data-ds="'+i+'" style="'+statColor(o[2])+';border-radius:6px;font-weight:600">'+opts+'</select></td>'+
    '<td><label class="recv"><input type="checkbox" data-dr="'+i+'" '+(o[3]?'checked':'')+'>received</label></td>'+
    '<td><input data-dnote="'+i+'" value="'+esc(o[4])+'"></td><td><button class="rm" data-dx="'+i+'">x</button></td></tr>';
 });bindDocs();}
function bindDocs(){
  document.querySelectorAll('[data-dl]').forEach(function(e){e.oninput=function(){DOCS[+e.dataset.dl][1]=e.value;};});
  document.querySelectorAll('[data-ds]').forEach(function(e){e.onchange=function(){var i=+e.dataset.ds;DOCS[i][2]=e.value;DOCS[i][3]=(e.value==='Received');renderDocs();};});
  document.querySelectorAll('[data-dr]').forEach(function(e){e.onchange=function(){var i=+e.dataset.dr;DOCS[i][3]=e.checked;DOCS[i][2]=e.checked?'Received':(DOCS[i][2]==='Received'?'Waiting':DOCS[i][2]);renderDocs();};});
  document.querySelectorAll('[data-dnote]').forEach(function(e){e.oninput=function(){DOCS[+e.dataset.dnote][4]=e.value;};});
  document.querySelectorAll('[data-dx]').forEach(function(b){b.onclick=function(){DOCS.splice(+b.dataset.dx,1);renderDocs();};});
}
el('addDoc').onclick=function(){DOCS.push(["custom_"+Date.now().toString(36),"New item","Requested",false,""]);renderDocs();};

var CALLS=[["","Intro call: overview of services"]];
function renderCalls(){var b=el('calls');b.innerHTML='';CALLS.forEach(function(c,i){
  b.innerHTML+='<tr><td><input data-cd="'+i+'" value="'+esc(c[0])+'" placeholder="date"></td><td><input data-cn="'+i+'" value="'+esc(c[1])+'"></td><td><button class="rm" data-cr="'+i+'">x</button></td></tr>';
 });
  document.querySelectorAll('[data-cd]').forEach(function(e){e.oninput=function(){CALLS[+e.dataset.cd][0]=e.value;};});
  document.querySelectorAll('[data-cn]').forEach(function(e){e.oninput=function(){CALLS[+e.dataset.cn][1]=e.value;};});
  document.querySelectorAll('[data-cr]').forEach(function(b){b.onclick=function(){CALLS.splice(+b.dataset.cr,1);renderCalls();};});
}
el('addCall').onclick=function(){CALLS.push(["",""]);renderCalls();};

// ---- Pricing (internal; toggles off the setup-team handoff) ----
var PRICE={membership:{tier:'',monthly:'',setup:''},lines:[],discount:'',note:''};
var showPrice=true;
function n(v){var x=parseFloat((v||'').toString().replace(/[^0-9.\-]/g,''));return isNaN(x)?0:x;}
function money(x){return '$'+(Math.round(x*100)/100).toLocaleString('en-US',{maximumFractionDigits:2});}
function renderPrice(){
  el('pm_tier').value=PRICE.membership.tier||'';el('pm_monthly').value=PRICE.membership.monthly||'';el('pm_setup').value=PRICE.membership.setup||'';
  el('p_discount').value=PRICE.discount||'';el('p_note').value=PRICE.note||'';
  var b=el('plines');b.innerHTML='';
  PRICE.lines.forEach(function(l,i){
    b.innerHTML+='<tr><td><input data-pl="'+i+'" value="'+esc(l.label)+'"></td>'+
      '<td class="num"><input data-pmn="'+i+'" class="pnum" value="'+esc(l.monthly)+'"></td>'+
      '<td class="num"><input data-pst="'+i+'" class="pnum" value="'+esc(l.setup)+'"></td>'+
      '<td><button class="rm" data-plx="'+i+'">x</button></td></tr>';
  });
  b.querySelectorAll('[data-pl]').forEach(function(e){e.oninput=function(){PRICE.lines[+e.dataset.pl].label=e.value;};});
  b.querySelectorAll('[data-pmn]').forEach(function(e){e.oninput=function(){PRICE.lines[+e.dataset.pmn].monthly=e.value;calcPrice();};});
  b.querySelectorAll('[data-pst]').forEach(function(e){e.oninput=function(){PRICE.lines[+e.dataset.pst].setup=e.value;calcPrice();};});
  b.querySelectorAll('[data-plx]').forEach(function(bx){bx.onclick=function(){PRICE.lines.splice(+bx.dataset.plx,1);renderPrice();};});
  calcPrice();
}
function calcPrice(){
  var m=n(PRICE.membership.monthly),s=n(PRICE.membership.setup);
  PRICE.lines.forEach(function(l){m+=n(l.monthly);s+=n(l.setup);});
  var d=n(PRICE.discount);
  el('t_month').textContent=money(m);el('t_disc').textContent=money(d);el('t_net').textContent=money(m-d);el('t_setup').textContent=money(s);
}
el('pm_tier').oninput=function(){PRICE.membership.tier=el('pm_tier').value;};
el('pm_monthly').oninput=function(){PRICE.membership.monthly=el('pm_monthly').value;calcPrice();};
el('pm_setup').oninput=function(){PRICE.membership.setup=el('pm_setup').value;calcPrice();};
el('p_discount').oninput=function(){PRICE.discount=el('p_discount').value;calcPrice();};
el('p_note').oninput=function(){PRICE.note=el('p_note').value;};
el('addLine').onclick=function(){PRICE.lines.push({label:'',monthly:'',setup:''});renderPrice();};
el('fromSvc').onclick=function(){var have={};PRICE.lines.forEach(function(l){have[l.label]=1;});DIVS.forEach(function(d){d[1].forEach(function(it){var k=SVCKEYS[idxFor(d[0],it)];if(SEL[k]&&SEL[k].on&&!have[it]){PRICE.lines.push({label:it,monthly:'',setup:''});}});});renderPrice();};
function applyPriceVis(){el('priceCard').style.display=showPrice?'':'none';el('togPrice').textContent='Pricing: '+(showPrice?'shown':'HIDDEN');el('printBtn').textContent=showPrice?'Print / PDF (incl. pricing)':'Print / PDF (handoff: no pricing)';}
el('togPrice').onclick=function(){showPrice=!showPrice;applyPriceVis();};

var FIELDS=['company_legal','contact','referring_partner','status','folder','dba','fein','entity','website','industry','peo_placement','ft_w2','pt_w2','ic_1099','pay_frequency','gross_payroll','gross_revenue','states','current_payroll_provider','offering_benefits','health_carrier','benefits_broker','wc_status','wc_carrier','wc_expiration','time_attendance','software_replace','handoff'];

function getState(){
  var s={meta:{schema:'atlas-one-tracker/v2',prospect:el('company_legal').value,saved:new Date().toISOString(),status:el('status').value},fields:{},services:[],divisionNotes:DNOTE,documents:[],calls:[],handoff:el('handoff').value};
  FIELDS.forEach(function(f){s.fields[f]=el(f).value;});
  DIVS.forEach(function(d){d[1].forEach(function(it){var k=SVCKEYS[idxFor(d[0],it)];var v=SEL[k]||{on:false,detail:''};s.services.push({key:k,label:it,division:d[0],on:!!v.on,detail:v.detail||''});});});
  DOCS.forEach(function(o){s.documents.push({key:o[0],label:o[1],status:o[2],received:!!o[3],note:o[4]});});
  CALLS.forEach(function(c){s.calls.push({date:c[0],note:c[1]});});
  s.pricing={show:showPrice,membership:PRICE.membership,lines:PRICE.lines,discount:PRICE.discount,note:PRICE.note};
  return s;
}
function setState(s){
  s=s||{};
  var fld=s.fields||{};
  FIELDS.forEach(function(f){if(fld[f]!==undefined&&fld[f]!==null)el(f).value=fld[f];});
  if(s.meta&&s.meta.status)el('status').value=s.meta.status;
  // services
  SEL={};
  if(Array.isArray(s.services)){s.services.forEach(function(sv){if(sv&&sv.key)SEL[sv.key]={on:!!sv.on,detail:sv.detail||''};});}
  DNOTE=s.divisionNotes||{};
  // documents: keep default rows, merge saved by key, then append custom keys not in default
  if(Array.isArray(s.documents)&&s.documents.length){
    var map={}; s.documents.forEach(function(d){if(d&&d.key)map[d.key]=d;});
    var out=[];
    DOC_DEFAULT.forEach(function(dd){var m=map[dd[0]];if(m){out.push([dd[0],m.label||dd[1],m.status||dd[2],!!m.received,m.note||'']);delete map[dd[0]];}else{out.push(dd.slice());}});
    s.documents.forEach(function(d){if(d&&d.key&&map[d.key]){out.push([d.key,d.label||'',d.status||'Requested',!!d.received,d.note||'']);delete map[d.key];}});
    DOCS=out;
  } else {DOCS=JSON.parse(JSON.stringify(DOC_DEFAULT));}
  CALLS=(Array.isArray(s.calls)&&s.calls.length)?s.calls.map(function(c){return [c.date||'',c.note||''];}):[["","Intro call: overview of services"]];
  if(s.handoff!==undefined)el('handoff').value=s.handoff;
  if(s.pricing){var pr=s.pricing;PRICE={membership:(pr.membership||{tier:'',monthly:'',setup:''}),lines:(Array.isArray(pr.lines)?pr.lines:[]),discount:pr.discount||'',note:pr.note||''};showPrice=(pr.show!==false);}
  renderSvc();renderDocs();renderCalls();renderPrice();applyPriceVis();
}
function clearAll(){
  FIELDS.forEach(function(f){el(f).value='';});el('status').value='Gathering info';
  SEL={};DNOTE={};DOCS=JSON.parse(JSON.stringify(DOC_DEFAULT));CALLS=[["","Intro call: overview of services"]];
  PRICE={membership:{tier:'',monthly:'',setup:''},lines:[],discount:'',note:''};showPrice=true;
  renderSvc();renderDocs();renderCalls();renderPrice();applyPriceVis();
}
el('new').onclick=function(){if(confirm('Clear this form and start a new prospect? Save first if you need this record.'))clearAll();};
el('save').onclick=function(){var st=getState();var name=(el('company_legal').value||'prospect').replace(/[^a-z0-9]+/gi,'_');var blob=new Blob([JSON.stringify(st,null,2)],{type:'application/json'});var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Atlas_One_Tracker_'+name+'.json';a.click();};
el('load').onclick=function(){el('file').click();};
el('file').onchange=function(e){var f=e.target.files[0];if(!f)return;var r=new FileReader();r.onload=function(){try{setState(JSON.parse(r.result));}catch(err){alert('Could not read that file. Make sure it is an Atlas One tracker JSON.');}};r.readAsText(f);e.target.value='';};
el('openFolder').onclick=function(){var p=el('folder').value.trim();if(!p){alert('Enter the prospect folder path first.');return;}var url=p.indexOf('file://')===0?p:'file://'+(p[0]==='/'?'':'/')+p;window.open(url,'_blank');};
el('copyFolder').onclick=function(){var p=el('folder').value.trim();if(!p)return;if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(p);}else{var t=document.createElement('textarea');t.value=p;document.body.appendChild(t);t.select();document.execCommand('copy');t.remove();}el('copyFolder').textContent='Copied';setTimeout(function(){el('copyFolder').textContent='Copy path';},1200);};
renderSvc();renderDocs();renderCalls();renderPrice();applyPriceVis();

