var ndaType = 'mutual';

/* ---------- UI helpers ---------- */
function toggleSec(head){ head.parentElement.classList.toggle('collapsed'); }

function setType(t){
  ndaType = t;
  document.querySelectorAll('.seg-opt').forEach(function(el){
    el.classList.toggle('active', el.getAttribute('data-type')===t);
  });
  // update party role labels
  if(t==='mutual'){
    document.getElementById('lblA').innerHTML = 'Party A <span class="hint">(Disclosing &amp; Receiving Party)</span>';
    document.getElementById('lblB').innerHTML = 'Party B <span class="hint">(Disclosing &amp; Receiving Party)</span>';
  } else {
    document.getElementById('lblA').innerHTML = 'Party A <span class="hint">(Disclosing Party)</span>';
    document.getElementById('lblB').innerHTML = 'Party B <span class="hint">(Receiving Party)</span>';
  }
  render();
}

function openModal(){ document.getElementById('modal').classList.add('open'); }
function closeModal(){ document.getElementById('modal').classList.remove('open'); }
document.addEventListener('keydown', function(e){ if(e.key==='Escape') closeModal(); });

/* ---------- value + fill helpers ---------- */
function val(id){ var e=document.getElementById(id); return e? e.value.trim() : ''; }
function chk(id){ var e=document.getElementById(id); return e? e.checked : false; }
function esc(s){ return (s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
/* fill: show value, or a highlighted placeholder if empty */
function fill(v, placeholder){
  if(v && v.length){ return '<span class="fillmark">'+esc(v)+'</span>'; }
  return '<span class="fillmark empty">['+placeholder+']</span>';
}
function fmtDate(d){
  if(!d) return '';
  var parts = d.split('-'); if(parts.length!==3) return d;
  var months=["January","February","March","April","May","June","July","August","September","October","November","December"];
  return months[parseInt(parts[1],10)-1]+' '+parseInt(parts[2],10)+', '+parts[0];
}

/* ---------- main render ---------- */
function render(){
  var A = val('partyA'), B = val('partyB');
  var Aname = A || 'Party A', Bname = B || 'Party B';
  var mutual = (ndaType==='mutual');

  var aFill = fill(A, 'Party A name');
  var bFill = fill(B, 'Party B name');

  var sections = [];
  var n = 0;
  function num(){ n++; return n; }

  // ---- Title / intro ----
  var typeLabel = mutual ? 'MUTUAL NON-DISCLOSURE AGREEMENT' : 'NON-DISCLOSURE AGREEMENT';
  var typeSub = mutual ? 'Two-Way / Mutual' : 'One-Way / Unilateral';

  var effStr = val('effDate') ? '<span class="fillmark">'+fmtDate(val('effDate'))+'</span>' : '<span class="fillmark empty">[effective date]</span>';

  var intro;
  if(mutual){
    intro = 'This Mutual Non-Disclosure Agreement (the "Agreement") is entered into as of '+effStr+' (the "Effective Date"), by and between '+aFill+
      (val('addrA')?', located at '+fill(val('addrA'),'address'):'')+' ("'+esc(Aname)+'"), and '+bFill+
      (val('addrB')?', located at '+fill(val('addrB'),'address'):'')+' ("'+esc(Bname)+'"). '+
      'Each party may disclose to and receive Confidential Information from the other. Each party, in its capacity as the party disclosing Confidential Information, is a "Disclosing Party," and each party, in its capacity as the party receiving Confidential Information, is a "Receiving Party." '+esc(Aname)+' and '+esc(Bname)+' are collectively the "Parties."';
  } else {
    intro = 'This Non-Disclosure Agreement (the "Agreement") is entered into as of '+effStr+' (the "Effective Date"), by and between '+aFill+
      (val('addrA')?', located at '+fill(val('addrA'),'address'):'')+' (the "Disclosing Party"), and '+bFill+
      (val('addrB')?', located at '+fill(val('addrB'),'address'):'')+' (the "Receiving Party"). '+
      'The Disclosing Party wishes to disclose certain confidential and proprietary information to the Receiving Party, and the Receiving Party agrees to protect such information under the terms of this Agreement. The Disclosing Party and the Receiving Party are collectively the "Parties."';
  }

  // role phrasing helpers
  var receiving = mutual ? 'the Receiving Party' : 'the Receiving Party';
  var disclosing = mutual ? 'the Disclosing Party' : 'the Disclosing Party';
  var recCap = mutual ? 'each Receiving Party' : 'the Receiving Party';

  // ---- 1. Purpose ----
  var purpose = val('purpose');
  sections.push(clause(num()+'. Purpose',
    'The Parties wish to explore and/or engage in a business relationship concerning '+
    fill(purpose,'purpose of disclosure')+
    ' (the "Purpose"). In connection with the Purpose, '+(mutual?'each Disclosing Party':'the Disclosing Party')+
    ' may disclose to '+(mutual?'the other party':'the Receiving Party')+' certain Confidential Information as defined below.'));

  // ---- 2. Definition of Confidential Information ----
  var ci = 'For purposes of this Agreement, "Confidential Information" means any and all non-public, proprietary, or confidential information disclosed by '+disclosing+' to '+receiving+', whether orally, in writing, electronically, or by inspection of tangible objects, that is designated as confidential or that reasonably should be understood to be confidential given the nature of the information and the circumstances of disclosure.';
  var ciEx = val('ciExamples');
  var exampleText = ciEx ? esc(ciEx) : 'business plans, financial information, customer and client lists, pricing, methods, processes, software, technical data, trade secrets, and know-how';
  ci += ' Confidential Information includes, without limitation: '+
    (ciEx ? '<span class="fillmark">'+exampleText+'</span>' : exampleText)+'.';
  sections.push(clause(num()+'. Definition of Confidential Information', ci));

  // ---- 3. Exclusions ----
  sections.push(clauseList(num()+'. Exclusions from Confidential Information',
    'Confidential Information does not include information that '+receiving+' can demonstrate:',
    [
      'is or becomes publicly available through no wrongful act or breach of this Agreement by '+receiving+';',
      'was already known to '+receiving+' prior to disclosure, without an obligation of confidentiality;',
      'is independently developed by '+receiving+' without use of or reference to the Confidential Information; or',
      'is rightfully received from a third party who is not under a duty of confidentiality to '+disclosing+'.'
    ]));

  // ---- 4. Obligations ----
  var obl = (mutual?'Each Receiving Party':'The Receiving Party')+' agrees to: (a) use the Confidential Information solely for the Purpose and for no other purpose; (b) protect the Confidential Information using at least the same degree of care it uses for its own confidential information, and in no event less than a reasonable degree of care; and (c) not disclose the Confidential Information to any third party without the prior written consent of '+disclosing+', except to its employees, agents, or advisors who have a legitimate need to know for the Purpose and who are bound by confidentiality obligations at least as protective as those in this Agreement.';
  sections.push(clause(num()+'. Obligations of '+(mutual?'the Receiving Party':'the Receiving Party'), obl));

  // ---- 5. Term & Survival ----
  var term = val('termYears') || '2';
  var surv = val('survivalYears') || '3';
  sections.push(clause(num()+'. Term and Survival',
    'This Agreement shall commence on the Effective Date and continue for a period of <span class="fillmark">'+esc(term)+'</span> year(s), unless earlier terminated by either party upon written notice. The obligations of confidentiality set forth herein shall survive the termination or expiration of this Agreement and continue for a period of <span class="fillmark">'+esc(surv)+'</span> year(s) thereafter, or, with respect to any Confidential Information that constitutes a trade secret, for as long as such information remains a trade secret under applicable law.'));

  // ---- 6. Return/Destruction ----
  if(chk('optReturn')){
    sections.push(clause(num()+'. Return or Destruction of Materials',
      'Upon the termination or expiration of this Agreement, or upon written request by '+disclosing+', '+recCap+' shall promptly return or destroy all materials containing Confidential Information, including all copies, notes, and derivatives thereof, and shall, upon request, certify in writing that it has done so. Notwithstanding the foregoing, '+receiving+' may retain one copy solely for legal or compliance archival purposes, subject to continuing confidentiality obligations.'));
  }

  // ---- Optional: Non-solicitation ----
  if(chk('optNonSolicit')){
    sections.push(clause(num()+'. Non-Solicitation',
      'During the term of this Agreement and for a period of one (1) year thereafter, '+recCap+' shall not, directly or indirectly, solicit for employment or hire any employee of '+disclosing+', nor solicit the clients or customers of '+disclosing+' whose identity became known to it through the Confidential Information, without the prior written consent of '+disclosing+'.'));
  }

  // ---- Optional: No license ----
  if(chk('optNoLicense')){
    sections.push(clause(num()+'. No License or Rights Granted',
      'Nothing in this Agreement shall be construed as granting '+receiving+' any license, right, title, or interest in or to any Confidential Information, patent, copyright, trademark, trade secret, or other intellectual property of '+disclosing+', whether by implication, estoppel, or otherwise. All Confidential Information remains the sole and exclusive property of '+disclosing+'.'));
  }

  // ---- Optional: No warranty ----
  if(chk('optNoWarranty')){
    sections.push(clause(num()+'. No Warranty',
      'All Confidential Information is provided "AS IS." '+(mutual?'Each Disclosing Party':'The Disclosing Party')+' makes no representations or warranties, express or implied, as to the accuracy or completeness of the Confidential Information, and shall have no liability to '+receiving+' resulting from its use of the Confidential Information.'));
  }

  // ---- Optional: Injunctive relief ----
  if(chk('optInjunction')){
    sections.push(clause(num()+'. Remedies and Injunctive Relief',
      (mutual?'Each party':'The Receiving Party')+' acknowledges that any breach or threatened breach of this Agreement may cause irreparable harm to '+disclosing+' for which monetary damages would be an inadequate remedy. Accordingly, '+disclosing+' shall be entitled to seek injunctive and other equitable relief, without the necessity of posting a bond, in addition to any other remedies available at law or in equity.'));
  }

  // ---- Optional: Governing law ----
  if(chk('optGovLaw')){
    var st = val('govState') || 'Utah';
    sections.push(clause(num()+'. Governing Law',
      'This Agreement shall be governed by and construed in accordance with the laws of the State of <span class="fillmark">'+esc(st)+'</span>, without regard to its conflict-of-laws principles.'));
  }

  // ---- Optional: Dispute resolution ----
  if(chk('optDispute')){
    var dm = val('disputeMethod');
    var stForCourt = (chk('optGovLaw') ? (val('govState')||'Utah') : '');
    var courtLoc = stForCourt ? ' located in the State of <span class="fillmark">'+esc(stForCourt)+'</span>' : '';
    var dtext;
    if(dm==='arbitration'){
      dtext = 'Any dispute, controversy, or claim arising out of or relating to this Agreement shall be finally resolved by binding arbitration administered under the rules of a mutually agreed arbitration body. Judgment on the award rendered by the arbitrator(s) may be entered in any court having jurisdiction. The prevailing party shall be entitled to recover its reasonable attorneys’ fees and costs.';
    } else if(dm==='mediation'){
      dtext = 'In the event of any dispute arising out of or relating to this Agreement, the Parties shall first attempt in good faith to resolve the dispute through confidential mediation. If the dispute is not resolved within thirty (30) days of a written request to mediate, either party may pursue any remedy available in the courts'+courtLoc+'.';
    } else {
      dtext = 'The Parties consent to the exclusive jurisdiction of the state and federal courts'+courtLoc+' for the resolution of any dispute arising out of or relating to this Agreement, and waive any objection to venue in such courts. The prevailing party in any such action shall be entitled to recover its reasonable attorneys’ fees and costs.';
    }
    sections.push(clause(num()+'. Dispute Resolution', dtext));
  }

  // ---- Miscellaneous ----
  var misc = [];
  if(chk('optEntire')) misc.push('<b>Entire Agreement.</b> This Agreement constitutes the entire understanding between the Parties concerning its subject matter and supersedes all prior or contemporaneous agreements, whether written or oral.');
  if(chk('optAmend')) misc.push('<b>Amendments.</b> No amendment or modification of this Agreement shall be effective unless made in writing and signed by both Parties.');
  if(chk('optSever')) misc.push('<b>Severability.</b> If any provision of this Agreement is held to be invalid or unenforceable, the remaining provisions shall continue in full force and effect.');
  if(chk('optWaiver')) misc.push('<b>No Waiver.</b> The failure of either party to enforce any provision of this Agreement shall not constitute a waiver of that or any other provision.');
  if(chk('optAssign')) misc.push('<b>Assignment.</b> Neither party may assign this Agreement or any of its rights or obligations hereunder without the prior written consent of the other party, except in connection with a merger, acquisition, or sale of substantially all of its assets.');
  if(misc.length){
    var mi = num()+'. Miscellaneous';
    var body = '<ul>'+misc.map(function(m){return '<li>'+m+'</li>';}).join('')+'</ul>';
    sections.push('<div class="clause"><h3>'+mi+'</h3>'+body+'</div>');
  }

  // ---- Signature intro ----
  sections.push(clause(num()+'. Acceptance',
    'IN WITNESS WHEREOF, the Parties have executed this Agreement as of the Effective Date.'));

  // ---- Signature blocks ----
  var sigA = sigBlock(Aname, val('sigNameA'), val('sigTitleA'));
  var sigB = sigBlock(Bname, val('sigNameB'), val('sigTitleB'));
  var sigHTML = '<div class="sig-wrap">'+sigA+sigB+'</div>';

  // ---- assemble ----
  var html =
    '<h2 class="doc-title">'+typeLabel+'</h2>'+
    '<div class="doc-sub">'+typeSub+' &middot; Atlas One Solutions</div>'+
    '<p class="intro">'+intro+'</p>'+
    sections.join('')+
    sigHTML+
    '<div class="doc-disclaimer"><b>Disclaimer:</b> This tool generates a general-purpose NDA and is not legal advice. Have it reviewed by an attorney for your specific situation and state.</div>';

  document.getElementById('document').innerHTML = html;

  // sub-option show/hide
  document.getElementById('govLawSub').classList.toggle('hidden', !chk('optGovLaw'));
  document.getElementById('disputeSub').classList.toggle('hidden', !chk('optDispute'));
}

function clause(title, body){
  return '<div class="clause"><h3>'+title+'</h3><p>'+body+'</p></div>';
}
function clauseList(title, lead, items){
  return '<div class="clause"><h3>'+title+'</h3><p>'+lead+'</p><ul>'+
    items.map(function(i){return '<li>'+i+'</li>';}).join('')+'</ul></div>';
}
function sigBlock(party, name, title){
  return '<div class="sig-col">'+
    '<div class="sig-party">'+esc(party)+'</div>'+
    '<div class="sig-line"></div><div class="sig-cap">Signature</div>'+
    '<div class="sig-line" style="margin-top:16px;"></div><div class="sig-cap">Name: '+(name?esc(name):'')+'</div>'+
    '<div class="sig-line" style="margin-top:16px;"></div><div class="sig-cap">Title: '+(title?esc(title):'')+'</div>'+
    '<div class="sig-line" style="margin-top:16px;"></div><div class="sig-cap">Date</div>'+
    '</div>';
}

