/* Atlas One client-logo module. Self-contained; no dependency on the host page's
   render function. Re-applies on DOM change so it survives a full re-render. */
(function(){
  var DOC_SEL = "#document", FORM_SEL = ".panel-form";
  var LOGO = '', busy = false, mo = null;

  function apply(){
    if (busy) return;
    busy = true;
    try {
      var docs = document.querySelectorAll(DOC_SEL);
      for (var i = 0; i < docs.length; i++) {
        var d = docs[i];
        var img = d.querySelector(':scope > img.a1-doclogo');
        if (!LOGO) { if (img) img.parentNode.removeChild(img); continue; }
        if (!img) {
          img = document.createElement('img');
          img.className = 'a1-doclogo';
          img.alt = 'Company logo';
          d.insertBefore(img, d.firstChild);
        }
        if (img.getAttribute('src') !== LOGO) img.setAttribute('src', LOGO);
      }
    } catch (e) { /* never let the logo break the tool */ }
    setTimeout(function(){ busy = false; }, 0);
  }

  function onPick(e){
    var f = e.target.files && e.target.files[0];
    if (!f) return;
    if (f.size > 4 * 1024 * 1024) { alert('That image is larger than 4 MB. Please use a smaller file.'); e.target.value=''; return; }
    var r = new FileReader();
    r.onload = function(){
      LOGO = r.result;
      var p = document.getElementById('a1LogoPrev');
      if (p) { p.src = LOGO; p.style.display = 'inline-block'; }
      var l = document.getElementById('a1LogoLab');
      if (l) l.textContent = 'Logo added';
      var c = document.getElementById('a1LogoClr');
      if (c) c.style.display = 'inline-block';
      apply();
    };
    r.readAsDataURL(f);
  }

  function clearLogo(){
    LOGO = '';
    var p = document.getElementById('a1LogoPrev'); if (p) { p.removeAttribute('src'); p.style.display='none'; }
    var l = document.getElementById('a1LogoLab');  if (l) l.textContent = 'Add your company logo';
    var c = document.getElementById('a1LogoClr');  if (c) c.style.display = 'none';
    var f = document.getElementById('a1LogoFile'); if (f) f.value = '';
    apply();
  }

  function build(){
    if (document.getElementById('a1LogoFile')) return;
    var box = document.createElement('div');
    box.className = 'a1-logo-ctl no-print';
    box.innerHTML =
      '<input type="file" id="a1LogoFile" accept="image/png,image/jpeg,image/svg+xml,image/webp">' +
      '<img class="a1-prev" id="a1LogoPrev" alt="">' +
      '<div class="a1-txt">' +
        '<label class="a1-lab" id="a1LogoLab" for="a1LogoFile">Add your company logo</label>' +
        '<div class="a1-hint">Prints at the top of the document. PNG or SVG works best.</div>' +
      '</div>' +
      '<div class="a1-acts">' +
        '<button type="button" class="a1-btn" id="a1LogoBtn">Upload</button>' +
        '<button type="button" class="a1-clear" id="a1LogoClr">Remove</button>' +
      '</div>';

    var host = document.querySelector(FORM_SEL);
    if (host) {
      // slot it under the panel's own heading rather than above it
      var head = host.querySelector('h2, h3, .section-label, .panel-head');
      if (head && head.parentNode === host) host.insertBefore(box, head.nextSibling);
      else host.insertBefore(box, host.firstChild);
    } else {
      box.style.cssText += ';position:fixed;top:12px;right:12px;z-index:9999;max-width:420px;' +
                           'background:#fff;box-shadow:0 8px 26px rgba(35,48,77,.20)';
      document.body.appendChild(box);
    }
    document.getElementById('a1LogoFile').addEventListener('change', onPick);
    document.getElementById('a1LogoBtn').addEventListener('click', function(){
      document.getElementById('a1LogoFile').click();
    });
    document.getElementById('a1LogoClr').addEventListener('click', clearLogo);
    document.getElementById('a1LogoClr').style.display = 'none';

    mo = new MutationObserver(function(){ if (!busy && LOGO) apply(); });
    mo.observe(document.body, { childList: true, subtree: true });
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', build);
  else build();
})();


