/* ============ US STATES ============ */
var STATES=["Alabama","Alaska","Arizona","Arkansas","California","Colorado","Connecticut","Delaware","District of Columbia","Florida","Georgia","Hawaii","Idaho","Illinois","Indiana","Iowa","Kansas","Kentucky","Louisiana","Maine","Maryland","Massachusetts","Michigan","Minnesota","Mississippi","Missouri","Montana","Nebraska","Nevada","New Hampshire","New Jersey","New Mexico","New York","North Carolina","North Dakota","Ohio","Oklahoma","Oregon","Pennsylvania","Rhode Island","South Carolina","South Dakota","Tennessee","Texas","Utah","Vermont","Virginia","Washington","West Virginia","Wisconsin","Wyoming"];
(function(){
  var sel=document.getElementById('govState');
  for(var i=0;i<STATES.length;i++){
    var o=document.createElement('option');o.value=STATES[i];o.textContent=STATES[i];
    if(STATES[i]==='Utah')o.selected=true;
    sel.appendChild(o);
  }
})();

/* ============ UI HELPERS ============ */
function toggleSection(head){head.parentElement.classList.toggle('collapsed');}
function syncRow(id){
  var cb=document.getElementById('cl_'+id);
  var row=document.getElementById('row_'+id);
  if(cb&&row)row.classList.toggle('on',cb.checked);
}
function openModal(){document.getElementById('modal').classList.add('show');}
function closeModal(){document.getElementById('modal').classList.remove('show');}
document.addEventListener('keydown',function(e){if(e.key==='Escape')closeModal();});

/* ============ FORMATTING HELPERS ============ */
function val(id){var el=document.getElementById(id);return el?el.value.trim():'';}
function checked(id){var el=document.getElementById(id);return el?el.checked:false;}
function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function ph(text,placeholder){
  // returns escaped text, or a soft inline placeholder when empty
  if(text&&text.length)return esc(text);
  return '<span class="empty-inline">['+esc(placeholder)+']</span>';
}
function money(n){
  if(n===''||isNaN(parseFloat(n)))return '';
  var num=parseFloat(n);
  return '$'+num.toLocaleString('en-US',{minimumFractionDigits:(num%1?2:0),maximumFractionDigits:2});
}
function fmtDate(iso){
  if(!iso)return '';
  var parts=iso.split('-');
  if(parts.length!==3)return iso;
  var d=new Date(parseInt(parts[0]),parseInt(parts[1])-1,parseInt(parts[2]));
  var months=["January","February","March","April","May","June","July","August","September","October","November","December"];
  return months[d.getMonth()]+' '+d.getDate()+', '+d.getFullYear();
}
function today(){
  var d=new Date();
  var months=["January","February","March","April","May","June","July","August","September","October","November","December"];
  return months[d.getMonth()]+' '+d.getDate()+', '+d.getFullYear();
}

/* ============ MAIN RENDER ============ */
function render(){
  var company=val('companyName')||'Atlas One Solutions';
  var companyAddr=val('companyAddr');
  var repName=val('repName');
  var repTitle=val('repTitle');
  var empName=val('empName');
  var empAddr=val('empAddr');
  var title=val('title');
  var dept=val('dept');
  var reportsTo=val('reportsTo');
  var startDate=val('startDate');
  var locType=val('locType');
  var workLoc=val('workLoc');
  var empType=val('empType');
  var flsa=val('flsa');
  var schedule=val('schedule');
  var payType=val('payType');
  var payFreq=val('payFreq');
  var payAmount=val('payAmount');
  var bonus=val('bonus');
  var govState=val('govState')||'Utah';

  /* FLSA hint under the form */
  var fh=document.getElementById('flsaHint');
  if(flsa==='Exempt'){
    fh.textContent='Exempt: generally salaried and not eligible for overtime pay under the FLSA.';
  }else{
    fh.textContent='Non-exempt: eligible for overtime pay (typically 1.5× the regular rate over 40 hrs/week).';
  }

  /* State hint (Montana special case) */
  var sh=document.getElementById('stateHint');
  if(govState==='Montana'){
    sh.innerHTML='&#9888; Montana is not a pure at-will state (Wrongful Discharge from Employment Act). Have an attorney review before use.';
    sh.style.color='#23304D';
  }else{
    sh.textContent='At-will rules and required notices vary by state, review with counsel.';
    sh.style.color='';
  }

  var out='';

  /* ---- Letterhead ---- */
  out+='<div class="doc-head">';
  out+='<div class="doc-company">'+esc(company)+'</div>';
  if(companyAddr)out+='<div class="doc-company-addr">'+esc(companyAddr)+'</div>';
  out+='<div class="doc-title">Offer of Employment &amp; At-Will Agreement</div>';
  out+='<div class="doc-date">'+today()+'</div>';
  out+='</div>';

  /* ---- Greeting ---- */
  out+='<p class="greet">Dear '+ph(empName,'Employee Name')+',</p>';
  out+='<p>'+esc(company)+' ("the Company") is pleased to offer you ('+ph(empName,'Employee Name')+') the position of <strong>'+ph(title,'Position / Title')+'</strong>'+(dept?', in the '+esc(dept)+' department':'')+'. This letter sets out the terms of your offer and, together with the acknowledgment below, forms our agreement. Your employment with the Company is <strong>at-will</strong>, as described below.</p>';

  /* ---- Position & terms table ---- */
  out+='<h3>1. Position &amp; Terms of Employment</h3>';
  out+='<table class="terms-table">';
  out+=row('Employee',ph(empName,'Employee Name'));
  if(empAddr)out+=row('Employee address',esc(empAddr));
  out+=row('Position / Title',ph(title,'Position / Title'));
  if(dept)out+=row('Department',esc(dept));
  if(reportsTo)out+=row('Reports to',esc(reportsTo));
  out+=row('Start date',startDate?fmtDate(startDate):'<span class="empty-inline">[Start Date]</span>');
  out+=row('Employment type',esc(empType));
  out+=row('Work arrangement',esc(locType)+(workLoc?' … '+esc(workLoc):''));
  if(schedule)out+=row('Schedule / hours',esc(schedule));
  out+=row('FLSA classification',esc(flsa)+(flsa==='Exempt'?' (not eligible for overtime)':' (eligible for overtime)'));
  out+='</table>';

  /* ---- Compensation ---- */
  out+='<h3>2. Compensation</h3>';
  var amt=money(payAmount);
  var freqLabel=payFreq;
  var compSentence;
  if(amt){
    compSentence='You will be paid on a <strong>'+esc(payType.toLowerCase())+'</strong> basis at a rate of <strong>'+amt+' '+esc(freqLabel)+'</strong>, less applicable taxes and withholdings, payable in accordance with the Company’s standard payroll schedule.';
  }else{
    compSentence='You will be paid on a <strong>'+esc(payType.toLowerCase())+'</strong> basis at a rate of <span class="empty-inline">[amount] '+esc(freqLabel)+'</span>, less applicable taxes and withholdings, payable in accordance with the Company’s standard payroll schedule.';
  }
  out+='<p>'+compSentence+'</p>';
  if(flsa==='Non-exempt'){
    out+='<p>As a non-exempt employee, you are eligible for overtime pay at one-and-one-half (1.5) times your regular rate for hours worked over 40 in a workweek, as required by applicable law.</p>';
  }else{
    out+='<p>As an exempt employee, your compensation covers all hours worked and you are not eligible for overtime pay under the Fair Labor Standards Act.</p>';
  }
  if(bonus)out+='<p><strong>Bonus / Commission:</strong> '+esc(bonus)+'</p>';

  /* ---- Benefits ---- */
  var bH=val('benHealth'),bP=val('benPTO'),bR=val('benRetire'),bO=val('benOther');
  if(bH||bP||bR||bO){
    out+='<h3>3. Benefits</h3>';
    out+='<table class="terms-table">';
    if(bH)out+=row('Health / medical',esc(bH));
    if(bP)out+=row('Paid time off',esc(bP));
    if(bR)out+=row('Retirement',esc(bR));
    if(bO)out+=row('Other',esc(bO));
    out+='</table>';
    out+='<p style="font-size:12.5px;color:#66708a;">Benefits are subject to the terms of the applicable plan documents and may be changed or discontinued by the Company at any time.</p>';
  }

  /* ---- AT-WILL (prominent) ---- */
  out+='<h3>4. At-Will Employment</h3>';
  out+='<div class="atwill-box">';
  out+='<div class="lbl">At-Will Employment Statement</div>';
  out+='<p style="margin-bottom:8px;">Your employment with '+esc(company)+' is <strong>"at-will."</strong> This means that either you or the Company may terminate the employment relationship at any time, for any reason or no reason, with or without cause and with or without advance notice.</p>';
  out+='<p style="margin-bottom:8px;">Nothing in this letter, in any Company handbook or policy, or in any verbal statement is intended to create a contract of guaranteed or continued employment, or to guarantee employment for any specific period or under any specific terms.</p>';
  out+='<p style="margin-bottom:0;">Your at-will status can only be changed by a written agreement that is signed by both you and an authorized officer of the Company. No manager, supervisor, or representative other than an authorized officer has authority to alter the at-will nature of your employment.</p>';
  out+='</div>';

  /* ---- Optional clauses ---- */
  var clauses=[];
  if(checked('cl_conf'))clauses.push({t:'Confidentiality',b:'During and after your employment, you agree to hold in strict confidence, and not to use or disclose, any confidential, proprietary, or trade-secret information of the Company or its clients, except as required to perform your duties or as required by law.'});
  if(checked('cl_ip'))clauses.push({t:'Intellectual Property / Work-for-Hire Assignment',b:'All work product, inventions, and materials you create within the scope of your employment or using Company resources are "works made for hire" and are the sole property of the Company. You hereby assign to the Company all right, title, and interest in such work product and agree to assist the Company in perfecting its rights.'});
  if(checked('cl_nonsol'))clauses.push({t:'Non-Solicitation',b:'For a period of twelve (12) months following the end of your employment, you agree not to directly or indirectly solicit the Company’s clients, customers, or employees for a competing purpose, to the extent permitted by applicable law.'});
  if(checked('cl_return'))clauses.push({t:'Return of Company Property',b:'Upon the end of your employment for any reason, or upon request, you agree to promptly return all Company property in your possession, including documents, equipment, devices, keys, credentials, and confidential information.'});
  if(checked('cl_bg'))clauses.push({t:'Background Check Contingency',b:'This offer is contingent upon the successful completion of a background check satisfactory to the Company. The Company may withdraw this offer or end employment if the results are not satisfactory, consistent with applicable law.'});
  if(checked('cl_handbook'))clauses.push({t:'Employee Handbook Acknowledgment',b:'You agree to review and comply with the Company’s employee handbook and policies, which may be updated from time to time. The handbook is a set of guidelines and does not create a contract or alter the at-will nature of your employment.'});
  if(checked('cl_arb'))clauses.push({t:'Arbitration Agreement (Optional)',b:'To the extent permitted and enforceable under applicable state and federal law, you and the Company agree that covered disputes arising out of your employment will be resolved by final and binding arbitration rather than in court. This provision is optional and its enforceability varies by state; it should be reviewed by counsel before use.'});

  if(clauses.length){
    out+='<h3>5. Additional Terms</h3>';
    for(var i=0;i<clauses.length;i++){
      out+='<p class="clause"><span class="cnum">5.'+(i+1)+' '+esc(clauses[i].t)+'. </span>'+clauses[i].b+'</p>';
    }
  }

  /* ---- Contingencies ---- */
  var conts=[];
  if(checked('cl_i9'))conts.push('completion of Form I-9 and presentation of documents establishing your identity and authorization to work in the United States');
  if(checked('cl_ref'))conts.push('satisfactory reference checks');
  var contHeadNum=clauses.length?6:5;
  if(conts.length){
    out+='<h3>'+contHeadNum+'. Contingencies</h3>';
    out+='<p>This offer of employment is contingent upon '+joinList(conts)+'. If any contingency is not satisfied, the Company may withdraw this offer.</p>';
  }

  /* ---- Governing law ---- */
  var lawNum=contHeadNum+(conts.length?1:0);
  out+='<h3>'+lawNum+'. Governing Law</h3>';
  out+='<p>This agreement is governed by the laws of the State of <strong>'+esc(govState)+'</strong>, without regard to its conflict-of-laws principles. If any provision is found unenforceable, the remaining provisions remain in full force and effect.</p>';

  /* ---- Acknowledgment ---- */
  var ackNum=lawNum+1;
  out+='<h3>'+ackNum+'. Acknowledgment &amp; Acceptance</h3>';
  out+='<p>By signing below, you acknowledge that you have read and understood this offer and agreement, that your employment is <strong>at-will</strong>, and that this letter contains the full terms of the offer. Any prior verbal or written representations that conflict with these terms are superseded.</p>';

  /* ---- Signature blocks ---- */
  out+='<div class="sig-block">';
  out+='<div class="sig-col">';
  out+='<div class="sig-role">Employee</div>';
  out+='<div class="sig-line"></div>';
  out+='<div class="sig-meta">Signature<br>';
  out+='Name: '+ (empName?esc(empName):'_______________________') +'<br>';
  out+='Date: _______________________</div>';
  out+='</div>';
  out+='<div class="sig-col">';
  out+='<div class="sig-role">For '+esc(company)+'</div>';
  out+='<div class="sig-line"></div>';
  out+='<div class="sig-meta">Signature<br>';
  out+='Name: '+ (repName?esc(repName):'_______________________') +'<br>';
  out+='Title: '+ (repTitle?esc(repTitle):'_______________________') +'<br>';
  out+='Date: _______________________</div>';
  out+='</div>';
  out+='</div>';

  /* ---- Disclaimer ---- */
  out+='<div class="disclaimer-doc">Disclaimer: This tool generates a general-purpose at-will offer/agreement and is not legal advice. At-will rules and required notices vary by state (e.g., Montana), have it reviewed by an attorney before use.</div>';

  document.getElementById('doc').innerHTML=out;
}

function row(k,v){return '<tr><td class="k">'+k+'</td><td class="v">'+v+'</td></tr>';}
function joinList(arr){
  if(arr.length===1)return arr[0];
  if(arr.length===2)return arr[0]+' and '+arr[1];
  return arr.slice(0,-1).join(', ')+', and '+arr[arr.length-1];
}

